From 4ca7fd19017191f04546c2f90ab8b1d29e44459d Mon Sep 17 00:00:00 2001
From: tomas-muller <muller@unitime.org>
Date: Mon, 26 Oct 2015 17:01:34 +0100
Subject: [PATCH] iCalendar Exports

- ensure that the exported dates are in the local timezone
- this fixes the issue with daylight savings

diff --git a/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java b/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
index 16f51aee..f8a20c3c 100644
--- a/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
+++ b/JavaSource/org/unitime/timetable/gwt/server/CalendarServlet.java
@@ -83,11 +83,11 @@ import org.unitime.timetable.solver.service.SolverServerService;
 import org.unitime.timetable.util.Constants;
 import org.unitime.timetable.util.DateUtils;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
 import biweekly.component.VEvent;
 import biweekly.component.VFreeBusy;
+import biweekly.io.text.ICalWriter;
 import biweekly.parameter.Role;
 import biweekly.property.Attendee;
 import biweekly.property.CalendarScale;
@@ -273,11 +273,15 @@ public class CalendarServlet extends HttpServlet {
         }

 		PrintWriter out = response.getWriter();
+        ICalWriter writer = new ICalWriter(out, ICalVersion.V2_0);
 		try {
-            Biweekly.write(ical).go(out);
+	    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+        	writer.write(ical);
+        	writer.flush();
         	out.flush();
 		} finally {
 			out.close();
+			writer.close();
 		}
 	}


diff --git a/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java b/JavaSource/org/unitime/timetable/export/events/EventsExportEventsToICal.java
index 4bc4bc96..df580ea9 100644
