 import org.unitime.timetable.model.dao._RootDAO;
 import org.unitime.timetable.util.Constants;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
 import biweekly.component.VEvent;
+import biweekly.io.text.ICalWriter;
 import biweekly.parameter.Role;
 import biweekly.property.Attendee;
 import biweekly.property.CalendarScale;
@@ -104,7 +104,14 @@ public class EventsExportEventsToICal extends EventsExporter {
         for (EventInterface event: events)
 			print(ical, event);

-        Biweekly.write(ical).go(helper.getWriter());
+        ICalWriter writer = new ICalWriter(helper.getWriter(), ICalVersion.V2_0);
+    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+        try {
+        	writer.write(ical);
+        	writer.flush();
+        } finally {
+        	writer.close();
+        }
 	}

 	public boolean print(ICalendar ical, EventInterface event) throws IOException {

diff --git a/JavaSource/org/unitime/timetable/events/EventEmail.java b/JavaSource/org/unitime/timetable/events/EventEmail.java
index f434dcec..fb40c2f1 100644
--- a/JavaSource/org/unitime/timetable/events/EventEmail.java
+++ b/JavaSource/org/unitime/timetable/events/EventEmail.java
@@ -68,9 +68,9 @@ import org.unitime.timetable.security.rights.Right;
 import org.unitime.timetable.util.Constants;
 import org.unitime.timetable.util.NameFormat;

-import biweekly.Biweekly;
 import biweekly.ICalVersion;
 import biweekly.ICalendar;
+import biweekly.io.text.ICalWriter;
 import biweekly.property.CalendarScale;
 import biweekly.property.Method;
 import biweekly.property.Status;
@@ -340,8 +340,21 @@ public class EventEmail {
         		ical,
         		response().hasEventWithId() && response().getEvent().hasMeetings() ? response().getEvent() : request().getEvent(),
         		response().hasEventWithId() && response().getEvent().hasMeetings() ? null : Status.cancelled());
-
-		return (exp ? Biweekly.write(ical).go() : null);		
+        
+        if (exp) {
+        	StringWriter ret = new StringWriter();
+	        ICalWriter writer = new ICalWriter(ret, ICalVersion.V2_0);
+	    	writer.getTimezoneInfo().setDefaultTimeZone(TimeZone.getDefault());
+	        try {
+	        	writer.write(ical);
+	        	writer.flush();
+	        } finally {
+	        	writer.close();
+	        }
+	        return ret.toString();
+        } else {
+        	return null;
+        }
 	}

 	public static void eventExpired(Event cancelledEvent, Set<Meeting> cancelledMeetings) throws Exception {

